package com.obysoft.faithOS.entity;import java.time.LocalDateTime;import jakarta.persistence.*;@Entity @Table(name="attendance_device_audit")public class AttendanceDeviceAudit{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="device_id",length=80)private String deviceId;@ManyToOne@JoinColumn(name="church_id")private Church church;@Column(name="member_code",length=50)private String memberCode;@Column(nullable=false,length=30)private String outcome;@Column(name="remote_address",length=64)private String remoteAddress;@Column(name="occurred_at",nullable=false)private LocalDateTime occurredAt;@PrePersist void created(){occurredAt=LocalDateTime.now();}public void setDeviceId(String v){deviceId=v;}public void setChurch(Church v){church=v;}public void setMemberCode(String v){memberCode=v;}public void setOutcome(String v){outcome=v;}public void setRemoteAddress(String v){remoteAddress=v;}}
